const SEED_TIME: u64 = 1_800_000_000;

/// Synthetic pseudonymous actors. All addresses are generated by the
/// Soroban test environment; no real keys or identity data are included.
pub struct Actors {
    pub admin: Address,
    pub organization_owners: Vec<Address>,
    pub mentors: Vec<Address>,
    pub mentees: Vec<Address>,
}

