/// One complete synthetic story spanning the requested mentorship lifecycle.
/// Hashes stand in for all private text, documents, schedules, locations, and
/// evidence. Amounts are small test-token units, never real balances.
#[derive(Debug, PartialEq, Eq)]
pub struct Scenario {
    pub organizations: Vec<Organization>,
    pub mentors: Vec<Mentor>,
    pub mentees: Vec<Mentee>,
    pub programs: Vec<Program>,
    pub applications: Vec<Application>,
    pub matches: Vec<MentorshipMatch>,
    pub sessions: Vec<Session>,
    pub milestones: Vec<Milestone>,
    pub payments: Vec<Payment>,
    pub disputes: Vec<Dispute>,
}

/// An in-memory Soroban world plus its deterministic synthetic scenario.
/// It exists only in the host-side test crate and cannot be deployed.
pub struct World {
    pub env: Env,
    pub actors: Actors,
    pub scenario: Scenario,
    pub expertise: MentorExpertiseContractClient<'static>,
    pub profiles: MentorProfilesContractClient<'static>,
    pub delivery: MentorDeliveryContractClient<'static>,
}

impl World {
    pub fn seeded() -> Self {
        let env = Env::default();
        env.mock_all_auths();
        env.ledger().set_timestamp(SEED_TIME);

        let expertise_id = env.register(MentorExpertiseContract, ());
        let profiles_id = env.register(MentorProfilesContract, ());
        let delivery_id = env.register(MentorDeliveryContract, ());
        let expertise = MentorExpertiseContractClient::new(&env, &expertise_id);
        let profiles = MentorProfilesContractClient::new(&env, &profiles_id);
        let delivery = MentorDeliveryContractClient::new(&env, &delivery_id);

        let admin = Address::generate(&env);
        let organization_owners = (0..2).map(|_| Address::generate(&env)).collect();
        let mentors = (0..3).map(|_| Address::generate(&env)).collect();
        let mentees = (0..4).map(|_| Address::generate(&env)).collect();
        let actors = Actors {
            admin,
            organization_owners,
            mentors,
            mentees,
        };
        let scenario = Scenario::seed(&env, &actors);

        expertise.initialize(&actors.admin);
        seed_contract_surfaces(&env, &actors, &scenario, &expertise, &profiles, &delivery);

        Self {
            env,
            actors,
            scenario,
            expertise,
            profiles,
            delivery,
        }
    }
}

