fn seed_contract_surfaces(
    env: &Env,
    actors: &Actors,
    scenario: &Scenario,
    expertise: &MentorExpertiseContractClient,
    profiles: &MentorProfilesContractClient,
    delivery: &MentorDeliveryContractClient,
) {
    let software = id(env, 2, 0);
    let rust = id(env, 2, 1);
    let soroban = id(env, 2, 2);
    let security = id(env, 2, 3);
    expertise.register_skill(&actors.admin, &software, &None, &Symbol::new(env, "software"));
    expertise.register_skill(
        &actors.admin,
        &rust,
        &Some(software.clone()),
        &Symbol::new(env, "rust"),
    );
    expertise.register_skill(
        &actors.admin,
        &soroban,
        &Some(software.clone()),
        &Symbol::new(env, "soroban"),
    );
    expertise.register_skill(
        &actors.admin,
        &security,
        &Some(software),
        &Symbol::new(env, "security"),
    );
    expertise.publish_evidence_requirement(
        &actors.admin,
        &rust,
        &ProficiencyLevel::Proficient,
        &commitment(env, 90),
        &1,
    );

    for mentor in scenario.mentors.iter() {
        profiles.create_profile(
            &mentor.account,
            &mentor.profile_hash,
            &1,
            &ProfileVisibility::Public,
        );
    }

    for program in scenario.programs.iter() {
        let physical = matches!(program.mode, DeliveryMode::InPerson | DeliveryMode::Hybrid);
        delivery.configure_program(
            &program.owner,
            &program.id,
            &program.mode,
            &program.location_visibility,
            &program.location_hash,
            &program.safety_policy_hash,
            &physical,
            &1,
        );
    }
}

fn id(env: &Env, kind: u8, sequence: u8) -> BytesN<32> {
    let mut bytes = [0u8; 32];
    bytes[0] = b'M';
    bytes[1] = b'0';
    bytes[2] = kind;
    bytes[3] = sequence;
    BytesN::from_array(env, &bytes)
}

fn commitment(env: &Env, tag: u8) -> BytesN<32> {
    let mut bytes = [0xC7u8; 32];
    bytes[0] = b'C';
    bytes[1] = b'V';
    bytes[2] = tag;
    BytesN::from_array(env, &bytes)
}